#define A min( I.x, I.y )
#define I iResolution

float ring( vec3 p ){
    vec3 q = p;

	float sp = fract( atan( p.x, -p.y ) / 6.28  ),
          arc = .34,z =  fract( atan( p.x , q.y + .25 ) / 6.28 + arc ) - arc * 2.;

	p.z += sp * .305 - .1525;

	p.y *=  p.y < 0. ? abs(p.x) + .9 : 1.;

	return max(
        length( vec2(  length(p.xy) - .3, (p.z) ) )  - .06,
        z
    );
}

#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a) )
#define T( t ) fract( iTime * t ) * 12.566

float sh(vec2 u, float s) {
  /*

   |-----------|
   |  /     \  |
   | /   1   \ |
   | \   0   / |
   |  \  1  /  |
   |   \   /   |
   -------------

     max( abs(u.x), abs(u.y) ) - r;
     weight = r / cos( 30deg ) = r / 0.866025403784
     and linear map from abs(u.y)

  */

  if( (u.x < .05 && u.y < .0 ) ) return 1.;

  u = abs(u);

  return max(u.x - (s * 1.15470053837) * (1. - u.y / s / 2.), u.y - s);
}

float tex( vec2 u ){
    vec2 a = vec2(.1, sqrt(.0075)) / .4330127018;
    u -= a * round( u / a );
    return smoothstep( 5. / A, 0., abs(sh( u, .1 )) );
}

float df( vec3 p ){
	float d = 1., a = .002, b=a*.5;

    p += max(
        max(
            tex( p.xy ),
            tex( p.xz )
        ),
        tex( p.yz )
    ) * a - b;

    p.xz *= rot( T( .1 ) );
    p.zy *= rot( T( .1 ) );

	vec3 q = p;

	for( float i = 1.; i <= 3.; i++ ){
        p = q;

        p.xy *= rot( 2.094 * i );
        p.xz *= rot( 2.094 );
        p.y -= .2;

        d = min(
            d,
            ring(p)
        );
    }


	return d;
}


// get normal from IQ
vec3 l(in vec3 b) {
    vec3 n = vec3(0.0);
    for( int i=min(iFrame,0); i<4; i++ )
    {
        vec3 e = 0.5773*(2.0*vec3((((i+3)>>1)&1),((i>>1)&1),(i&1))-1.0);
        n += e*df(b+0.0005*e);
        if( n.x+n.y+n.z>100.0 ) break;
    }
    return normalize(n);
}

// high light from IQ

float S( vec3 p, vec3 ca, vec3 r, float q ){
    return clamp(pow( dot( l( p ), normalize( normalize( ca ) - r ) ), q ), 0., 1.);
}

float D;


vec4 tra( vec3 o, vec3 r, float it, int b ){
    vec3 c, p;

    float t, d, i, tmp, e;

    while( i++ < it ){
        p = o + r * t;

      	if( d - tmp < .001 ){
 			tmp = d;
        }

        d = df( p ) * .6667;

      	if( d - tmp > 1.5 / A && d - tmp < 3. / A  ){
        	e = 1. ;
        }

        t += d;

        if( d<1e-3 || t < .15 ){
            break ;
        }
    }

    D = d;


    if( d < 1e-3 ){

        vec3 lg = vec3( -.2, .3, -.7 );
        float fp = dot( l( p ), lg );


        if( fp < .6 ){
            for( float i = 1.; i < 3.; i++ ){
                c += dot( l( p ), vec3( 
                    sin(i) + 2. * sin(2. * i),
                    sin(3. * i),
                    cos( i ) - 2. * cos( 2. * i )
                ) * .1 - .05 );
            }
        }

        if( b == 0 ){

            c = mix(
                c,
                vec3(1),
                S( p, lg, r, 85. ) * clamp(fp,0.,1.)
            );


            lg = vec3( .0, .3, 10.2 );
            fp = dot( l( p ), lg );

            c += S( p, lg, r, 56. ) * clamp(fp,0.,1.);

            c += .1;

        }else{
            c += .3;
        }

    }

  	e *= clamp( d, 0., 1. );

    return vec4(
        c,
        e
    );
}



void mainImage( out vec4 U, in vec2 V )
{
    vec2 u = ( V * 2. - I.xy ) / A;

    u.y = abs(u.y + .5)-.5 * (u.y<-.8?abs(1.-u.x):1.);

    float T_ = fract( length(u)- fract(iTime*.5) );

    vec3 c = (tra(vec3(0,0,-1),vec3(u*-.5,1),32.,0).rgb * 1.7 + tex(u * smoothstep( 1.,.7, T_) ) ) * T_  * .4 * smoothstep( 2., .1, length(u) ), p, o = vec3( 0., 0., -1. ), r = vec3( u, 1. );

    vec4 mT = tra( o, r, 64., 0 );

    c += mT.rgb;

	c = mix(
    	c,
      	vec3( 1.1 ),
      	mT.a
    );

    if( D < 1e-3 ){

        for( float i = 1.; i < 6.; i++ ){
            vec4 C = tra( o * vec3( 1, 1, sin(5. / i / 2.) * 2. ), 
            r
            , 32., 1 );

            c += C.rgb * (1. - i / 6.);
            c = clamp( c, 0., 1. );


        }
    }


    U = vec4(c * smoothstep( 0., .6, V.y / I.y ), 1.0);
}
